let cleanup: () => void;
let t: Tenant;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); t = await createTenant("tie-a"); });
afterAll(() => cleanup());

describe("tie paging", () => {
  it("pages ties", async () => {
    const recipientId = t.userIds.member;
    await notificationRepo.insertNotifications(t.org.id, Array.from({ length: 7 }, () => ({
      recipientId, kind: "issue_assigned", title: "x", body: "y", href: "/", actorId: null, channels: ["in_app"],
    })) as never);
    for (const size of [1, 2, 3, 7, 10]) {
      const seen: string[] = [];
      let cursor: string | null = null;
      for (let i = 0; i < 20; i++) {
        const page: any = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId, unreadOnly: false, limit: size, cursor } as never);
        seen.push(...page.items.map((n: any) => n.id));
        cursor = page.nextCursor;
        if (!cursor) break;
      }
      const big: any = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId, unreadOnly: false, limit: 100 } as never);
      expect(seen).toEqual(big.items.map((n: any) => n.id));
      expect(new Set(seen).size).toBe(7);
    }
  });
});
